:root {
  --clr-parchment: #f2e8d5;
  --clr-ink: #2c1a0e;
  --clr-rust: #8b3a1a;
  --clr-rust-light: #c4622d;
  --clr-gold: #b5862a;
  --clr-gold-light: #e8c96a;
  --clr-track: #6b5a3e;
  --clr-track-light: #a8916e;
  --clr-done: #4a7c59;
  --clr-surface: #ede0c4;
  --clr-border: #c9a96e;
}

article.route-log {
  background-color: var(--clr-parchment);
  border: 3px solid var(--clr-gold);
  border-radius: 4px;
  width: 460px;
  padding: 0;
  overflow: hidden;
  outline: 1px solid var(--clr-track);
  outline-offset: -6px;
}

.log-header {
  background-color: var(--clr-ink);
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 14px;
}

.log-badge {
  background-color: var(--clr-rust);
  color: var(--clr-gold-light);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.1em;
  padding: 2px 6px;
  border-radius: 2px;
  text-transform: uppercase;
}

.log-number {
  color: var(--clr-gold-light);
  font-size: 20px;
  font-weight: 900;
  letter-spacing: 0.04em;
  line-height: 1;
}

.log-class {
  color: var(--clr-track-light);
  font-size: 10px;
  font-weight: 400;
  letter-spacing: 0.08em;
  margin-left: auto;
  text-transform: uppercase;
}

.log-meta {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 14px;
  background-color: var(--clr-surface);
  border-bottom: 2px solid var(--clr-border);
}

.meta-item {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.meta-item--right {
  margin-left: auto;
}

.meta-label {
  font-size: 8px;
  font-weight: 700;
  color: var(--clr-track);
  text-transform: uppercase;
  letter-spacing: 0.1em;
}

.meta-value {
  font-size: 12px;
  font-weight: 700;
  color: var(--clr-ink);
}

.meta-divider {
  font-size: 14px;
  color: var(--clr-rust);
  font-weight: 900;
  margin-top: 6px;
}

.log-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  border-bottom: 2px solid var(--clr-border);
}

.stat-box {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 8px 6px;
  margin: 0;
  border-right: 1px solid var(--clr-border);
  background-color: var(--clr-parchment);
  gap: 1px;
}

.stat-box:last-child {
  border-right: none;
}

.stat-box--accent {
  background-color: var(--clr-rust);
}

.stat-value {
  font-size: 17px;
  font-weight: 900;
  color: var(--clr-ink);
  line-height: 1;
}

.stat-box--accent .stat-value {
  color: var(--clr-gold-light);
}

.stat-label {
  font-size: 8px;
  font-weight: 600;
  color: var(--clr-track);
  text-transform: uppercase;
  letter-spacing: 0.07em;
  text-align: center;
}

.stat-box--accent .stat-label {
  color: var(--clr-parchment);
}

.log-stops {
  padding: 6px 14px 4px;
}

.stops-title {
  font-size: 8px;
  font-weight: 700;
  color: var(--clr-track);
  text-transform: uppercase;
  letter-spacing: 0.14em;
  margin: 0 0 4px 0;
  padding-bottom: 3px;
  border-bottom: 1px dashed var(--clr-border);
}

.stops-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.stop-item {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 3px 7px;
  border-radius: 2px;
}

.stop-item--done {
  background-color: var(--clr-surface);
}

.stop-item--active {
  background-color: var(--clr-rust);
}

.stop-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  border: 2px solid var(--clr-track);
  flex-shrink: 0;
}

.stop-item--done .stop-dot {
  background-color: var(--clr-done);
  border-color: var(--clr-done);
}

.stop-item--active .stop-dot {
  background-color: var(--clr-gold-light);
  border-color: var(--clr-gold-light);
}

.stop-name {
  font-size: 11px;
  font-weight: 700;
  color: var(--clr-ink);
  flex: 1;
}

.stop-item--active .stop-name {
  color: var(--clr-gold-light);
}

.stop-time {
  font-size: 10px;
  font-weight: 600;
  color: var(--clr-track);
}

.stop-item--active .stop-time {
  color: var(--clr-parchment);
}

.stop-status {
  font-size: 8px;
  font-weight: 700;
  color: var(--clr-track-light);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  width: 26px;
  text-align: right;
}

.stop-item--active .stop-status {
  color: var(--clr-gold-light);
}

.log-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 5px 14px;
  background-color: var(--clr-ink);
  margin-top: 6px;
}

.footer-engineer,
.footer-fireman {
  font-size: 9px;
  font-weight: 600;
  color: var(--clr-track-light);
  letter-spacing: 0.06em;
}

.footer-stamp {
  font-size: 10px;
  font-weight: 900;
  color: var(--clr-rust-light);
  letter-spacing: 0.2em;
  border: 2px solid var(--clr-rust);
  padding: 2px 7px;
  border-radius: 2px;
  text-transform: uppercase;
}
